import * as THREE from 'three';
import { createGame } from './world.js';

const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];
const ASSETS = '/assets';
const chapters = [
  { id: 'df1', number: 'CHAPTER I', name: 'DARKEST FEAR', subtitle: 'Where it began.', description: 'A desperate search through a haunted hospital. Find the way out before the light dies.', missions: ['The Hollow', 'The Ward', 'No Escape', 'The Last Light'], art: `${ASSETS}/df1/aa.png`, accent: 0xc98d55, levels: [
    { name: 'The Hollow', objective: 'FIND THE THREE SEALS', layout: ['#########','#..#....#','#..#.#..#','#....#..#','###..#..#','#.......#','#.##.##.#','#.......#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[1,6],[5,4]], enemy: [7,5], props: [[3,1,'altar'],[5,2,'tree'],[2,5,'coffin']] },
    { name: 'The Ward', objective: 'RESTORE POWER TO THE EXIT', layout: ['#########','#...#...#','#.#.#.#.#','#.#...#.#','#.###.#.#','#.....#.#','###.#...#','#.......#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[3,3],[1,6]], enemy: [7,5], props: [[2,2,'altar'],[6,3,'coffin'],[4,6,'tree']] },
    { name: 'No Escape', objective: 'UNLOCK THE CHAPEL DOOR', layout: ['#########','#.......#','###.###.#','#...#...#','#.#.#.#.#','#.#...#.#','#.#####.#','#.......#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[1,3],[3,7]], enemy: [6,5], props: [[4,3,'altar'],[1,5,'coffin'],[6,2,'tree']] },
    { name: 'The Last Light', objective: 'REACH THE SANCTUARY', layout: ['#########','#.......#','#.#####.#','#...#...#','###.#.###','#...#...#','#.#####.#','#.......#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[1,5],[4,7]], enemy: [7,5], props: [[4,1,'altar'],[2,3,'coffin'],[6,5,'tree']] },
  ] },
  { id: 'df2', number: 'CHAPTER II', name: 'GRIM OAK', subtitle: 'The woods are watching.', description: 'A village buried beneath ancient trees. Something has followed you into the forest.', missions: ['Grim Oak', 'The Village', 'The Forest', 'Old Roots'], art: `${ASSETS}/df2/aw.png`, accent: 0x9e8d60, levels: [
    { name: 'Grim Oak', objective: 'COLLECT THE THREE SIGILS', layout: ['#########','#.......#','#.###.#.#','#...#.#.#','###...#.#','#.......#','#.#####.#','#.......#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[3,3],[1,5]], enemy: [7,5], props: [[4,2,'tree'],[2,4,'tree'],[6,4,'altar']] },
    { name: 'The Village', objective: 'OPEN THE OLD GATE', layout: ['#########','#.......#','###.###.#','#...#...#','#.#...#.#','#.#####.#','#.......#','#.#####.#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[3,3],[1,6]], enemy: [7,5], props: [[2,2,'coffin'],[5,3,'altar'],[3,6,'tree']] },
    { name: 'The Forest', objective: 'FIND THE THREE RUNES', layout: ['#########','#.......#','#.#####.#','#.......#','#####.###','#.......#','#.#####.#','#.......#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[1,3],[7,5]], enemy: [5,5], props: [[3,1,'tree'],[5,3,'tree'],[2,5,'altar']] },
    { name: 'Old Roots', objective: 'SEAL THE HEART OF THE OAK', layout: ['#########','#.......#','#.#####.#','#...#...#','###.#.###','#...#...#','#.#####.#','#.......#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[3,3],[5,5]], enemy: [7,5], props: [[4,1,'altar'],[2,3,'tree'],[6,5,'coffin']] },
  ] },
