    { name: 'Nightmare', objective: 'FIND THE THREE SHARDS', layout: ['#########','#.......#','#.#####.#','#.......#','###.#####','#.......#','#.#####.#','#.......#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[1,3],[7,5]], enemy: [5,5], props: [[4,1,'coffin'],[2,3,'altar'],[5,6,'tree']] },
    { name: 'The Descent', objective: 'BREAK THE THREE CHAINS', layout: ['#########','#.......#','#.#####.#','#...#...#','###.#.###','#...#...#','#.#####.#','#.......#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[3,3],[5,5]], enemy: [7,5], props: [[4,1,'coffin'],[2,3,'tree'],[6,5,'altar']] },
    { name: 'The Dreamer', objective: 'FIND THE WAY THROUGH', layout: ['#########','#.......#','###.###.#','#...#...#','#.#...#.#','#.#.###.#','#.......#','#.#####.#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[3,3],[1,6]], enemy: [7,5], props: [[5,2,'coffin'],[2,4,'altar'],[5,6,'tree']] },
    { name: 'Awakening', objective: 'END THE NIGHTMARE', layout: ['#########','#.......#','#.#####.#','#.......#','###.#####','#.......#','#.#####.#','#.......#','#########'], start: [1,1], exit: [7,7], keys: [[7,1],[1,3],[7,5]], enemy: [5,5], props: [[4,1,'altar'],[3,3,'coffin'],[4,6,'tree']] },
  ] },
];
const state = { scene: 'home', chapter: 0, mission: 0, game: null, sound: null, renderer: null, lastSave: null };
const saved = (() => { try { return JSON.parse(localStorage.getItem('darkestFearSave') || '{}'); } catch { return {}; } })();
function saveProgress() { const data = { unlocked: saved.unlocked || [0], completed: saved.completed || [], chapter: state.chapter, mission: state.mission }; localStorage.setItem('darkestFearSave', JSON.stringify(data)); Object.assign(saved, data); }
function showScreen(name) { state.scene = name; $$('.screen').forEach(x => x.classList.toggle('active', x.id === name)); $('#gameHud').classList.toggle('active', name === 'playing'); $('#touchControls').classList.toggle('active', name === 'playing' && matchMedia('(pointer: coarse)').matches); }
function renderChapters() {
  const completed = saved.completed || [];
  $('#chapterList').innerHTML = chapters.map((chapter, i) => {
    const unlocked = i === 0 || (saved.unlocked || []).includes(i) || completed.includes(chapters[i - 1].id + '-3');
    const doneCount = chapter.levels.filter((_, n) => completed.includes(`${i}-${n}`)).length;
    return `<button class="chapter-card" data-chapter="${i}" style="--chapter-accent:#${chapter.accent.toString(16)}"><span class="chapter-art" style="background-image:linear-gradient(0deg,#060808a8,transparent),url('${chapter.art}')"></span><span class="card-content"><span class="chapter-number">${chapter.number}${unlocked ? '' : ' · LOCKED'}</span><h3>${chapter.name}</h3><p>${chapter.description}</p><span class="card-bottom"><span>${doneCount ? `${doneCount} / 4 MISSIONS CLEARED` : '4 MISSIONS'}</span><b>${unlocked ? '↗' : '⌑'}</b></span></span></button>`;
  }).join('');
  $$('.chapter-card').forEach(btn => btn.addEventListener('click', () => { const i = Number(btn.dataset.chapter); if (i > 0 && !(saved.unlocked || []).includes(i) && !(saved.completed || []).includes(chapters[i - 1].id + '-3')) { toast('SURVIVE THE PREVIOUS CHAPTER FIRST'); return; } state.chapter = i; state.mission = 0; startLevel(); });
}
function startLevel() { showScreen('playing'); $('#pauseModal').classList.remove('active'); $('#resultModal').classList.remove('active'); const ch = chapters[state.chapter], level = ch.levels[state.mission]; $('#missionChapter').textContent = ch.number; $('#missionName').textContent = level.name.toUpperCase(); $('#keyCount').textContent = `0 / ${level.keys.length}`; $('#hint').textContent = level.objective; state.game.start(level, ch.id, ch.accent); }
