export function createGame({ THREE, renderer, canvas, onHud, onToast, onCollect, onStep, onDoor, onEnd, onTorch }) {
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x090d0d);
  scene.fog = new THREE.FogExp2(0x080c0d, 0.045);
  const camera = new THREE.PerspectiveCamera(48, 1, 0.1, 100);
  const clock = new THREE.Clock();
  const world = new THREE.Group();
  scene.add(world);

  const mats = {};
  const material = (name, color, roughness = 0.88, extra = {}) => {
