  const darkMat = material('shadow', 0x090d0d, 1);
  let level = null;
  let chapterId = 'df1';
  let accent = 0xc98d55;
  let tiles = [];
  let walls = [];
  let seals = [];
  let batteries = [];
  let player = null;
  let enemy = null;
  let exit = null;
  let torch = null;
  let torchTarget = null;
  let playerGlow = null;
  let torchOn = true;
  let paused = true;
  let ended = false;
  let keysFound = 0;
  let battery = 100;
  let moveTime = 0;
  let enemyMoves = 0;
  let enemyCooldown = 0;
  let anim = 0;
  let lastDir = { x: 0, z: 1 };
  let playerCell = { x: 1, z: 1 };
  let enemyCell = { x: 7, z: 5 };
  let worldOffset = { x: 0, z: 0 };
  let lastHudAt = 0;
  let raf = 0;
  let disposed = false;

  function mesh(geometry, mat, parent = world) {
    const item = new THREE.Mesh(geometry, mat);
    item.castShadow = true;
    item.receiveShadow = true;
    parent.add(item);
    return item;
  }
  function box(parent, mat, x, y, z, sx, sy, sz, bevel = false) {
