    return new THREE.Vector3(x + worldOffset.x, y, z + worldOffset.z);
  }
  function clearWorld() {
    while (world.children.length) {
      const object = world.children.pop();
      object.parent = null;
      object.traverse?.(child => {
        if (child.geometry) child.geometry.dispose();
      });
    }
    tiles = []; walls = []; seals = []; batteries = [];
    player = enemy = exit = torch = torchTarget = playerGlow = null;
  }
  function addMenuScene() {
    clearWorld();
    scene.fog.density = 0.027;
    worldOffset = { x: 0, z: 0 };
    const ground = mesh(new THREE.PlaneGeometry(80, 80), material('menuGround', 0x171b19));
    ground.rotation.x = -Math.PI / 2; ground.position.y = -0.07;
    for (let i = 0; i < 13; i++) {
      const x = (i - 6) * 1.15;
      const h = 2.5 + Math.sin(i * 3.2) * 1.1;
      const pillar = box(world, material(`menuStone${i}`, i % 2 ? 0x343833 : 0x292f2c), x, h / 2, -3, 0.38 + (i % 3) * .12, h, .55, true);
      pillar.rotation.z = Math.sin(i * 4.1) * .09;
    }
    for (let i = 0; i < 18; i++) {
      const trunk = mesh(new THREE.CylinderGeometry(.13, .32, 4 + (i % 4) * .5, 6), material(`menuTree${i}`, i % 2 ? 0x292820 : 0x1d2421));
      trunk.position.set((i % 2 ? 1 : -1) * (4 + Math.floor(i / 2) * 1.3), 1.7, -1 - (i % 5) * 1.4);
      trunk.rotation.z = (i % 3 - 1) * .13;
    }
