    mesh(new THREE.CylinderGeometry(.18, .24, .82, 8), coatMat, person).position.y = .59;
    mesh(new THREE.SphereGeometry(.18, 12, 10), playerMat, person).position.y = 1.15;
    const flame = new THREE.PointLight(0xffb95c, 12, 9, 1.8); flame.position.set(.35, .9, -.1); person.add(flame);
    const ambient = new THREE.HemisphereLight(0x586363, 0x17130e, 1.05); scene.add(ambient);
    const moon = new THREE.DirectionalLight(0x9ca9aa, 1.25); moon.position.set(-4, 9, 5); scene.add(moon);
    camera.position.set(7.5, 5.2, 10.5); camera.lookAt(0, 1.1, -1.5);
    resize();
  }
  function addFloorTile(x, z, variation = 0) {
    const tile = mesh(new THREE.BoxGeometry(1, .14, 1), material(`tile${variation}`, variation ? 0x373a34 : 0x30332e));
    tile.position.copy(positionFor(x, z, -.11));
    tile.receiveShadow = true;
    tiles.push({ x, z, mesh: tile });
    if ((x * 7 + z * 11) % 5 === 0) {
      const crack = mesh(new THREE.BoxGeometry(.04, .008, .22), material('crack', 0x202421));
      crack.position.set(x + worldOffset.x + .18, -.03, z + worldOffset.z - .14);
