  }
  function addProp(x, z, type, idx) {
    const root = new THREE.Group(); world.add(root); root.position.set(x + worldOffset.x, 0, z + worldOffset.z);
    if (type === 'tree') {
      const trunk = mesh(new THREE.CylinderGeometry(.14, .23, 1.25, 7), woodMat, root); trunk.position.y = .58;
      for (let i = 0; i < 3; i++) {
        const limb = mesh(new THREE.CylinderGeometry(.045, .1, .7, 5), woodMat, root);
        limb.position.set((i - 1) * .18, .94 + i * .12, -.04); limb.rotation.z = (i - 1) * .52;
      }
      const crown = mesh(new THREE.ConeGeometry(.42 + idx % 2 * .12, .8, 6), material('foliage', chapterId === 'nightmare' ? 0x202322 : 0x33352a), root); crown.position.y = 1.44;
      root.scale.setScalar(.78);
    } else if (type === 'coffin') {
      const body = box(root, woodMat, 0, .28, 0, .5, .48, .82, true); body.rotation.y = idx % 2 ? .4 : -.25;
      const lid = box(root, material('coffinLid', 0x544332), 0, .55, -.03, .55, .1, .88, true); lid.rotation.y = body.rotation.y;
      for (let i = -1; i <= 1; i++) { const nail = mesh(new THREE.SphereGeometry(.035, 6, 5), metalMat, root); nail.position.set(i * .14, .61, -.45); }
    } else {
      const base = box(root, material('altar', 0x4b4940), 0, .33, 0, .7, .66, .7, true);
      const slab = box(root, material('altarTop', 0x666253), 0, .7, 0, .86, .12, .86, true);
      const symbol = mesh(new THREE.TorusGeometry(.2, .025, 5, 16), goldMat, root); symbol.position.y = .79; symbol.rotation.x = Math.PI / 2;
      const glow = new THREE.PointLight(0xd79c4f, .8, 2.4, 2); glow.position.y = .95; root.add(glow);
    }
    root.userData.baseY = 0;
  }
  function addSeal(x, z, i) {
    const root = new THREE.Group(); world.add(root); root.position.set(x + worldOffset.x, .44, z + worldOffset.z);
    const stone = mesh(new THREE.OctahedronGeometry(.2, 0), goldMat, root); stone.scale.set(.76, 1.5, .42); stone.rotation.z = .3;
    const ring = mesh(new THREE.TorusGeometry(.3, .018, 5, 20), material(`ring${i}`, 0xd4a158, .45, { emissive: 0x71400e, emissiveIntensity: 1 }), root);
    ring.rotation.x = Math.PI / 2; ring.scale.set(.75, 1, 1);
    const glow = new THREE.PointLight(0xe5a44c, 1.5, 2.7, 1.8); root.add(glow);
    seals.push({ x, z, root, collected: false, phase: i * 1.8 });
  }
  function addBattery(x, z, i) {
    const root = new THREE.Group(); world.add(root); root.position.set(x + worldOffset.x, .23, z + worldOffset.z);
    const caseMesh = mesh(new THREE.BoxGeometry(.25, .31, .18), material('cell', 0x80794f, .5, { emissive: 0x514114, emissiveIntensity: .7 }), root);
    const cap = mesh(new THREE.BoxGeometry(.11, .05, .2), metalMat, root); cap.position.y = .18;
    const lamp = new THREE.PointLight(0xd8bd68, .75, 2.3, 2); root.add(lamp);
    batteries.push({ x, z, root, taken: false, phase: i * 2.3 });
  }
  function createPlayer() {
    const root = new THREE.Group(); world.add(root);
    const body = mesh(new THREE.CapsuleGeometry(.22, .45, 4, 8), coatMat, root); body.position.y = .55;
    const head = mesh(new THREE.SphereGeometry(.18, 12, 10), material('skin', 0x8c7967), root); head.position.y = .98;
    const hood = mesh(new THREE.SphereGeometry(.205, 12, 9, 0, Math.PI * 2, 0, Math.PI * .58), material('hood', 0x242a29), root); hood.position.y = 1.04; hood.rotation.x = -.12;
    const armL = mesh(new THREE.CapsuleGeometry(.075, .31, 3, 6), coatMat, root); armL.position.set(-.27, .58, -.02); armL.rotation.z = -.25;
