function createEnemy() {
  const root = new THREE.Group(); world.add(root);
  const torso = mesh(new THREE.CapsuleGeometry(.25, .48, 4, 7), creatureMat, root); torso.position.y = .65; torso.scale.set(.9, 1.1, .72);
  const head = mesh(new THREE.SphereGeometry(.21, 10, 8), creatureMat, root); head.position.y = 1.27; head.scale.set(.84, 1.2, .8);
  const armL = mesh(new THREE.CapsuleGeometry(.085, .52, 3, 5), creatureMat, root); armL.position.set(-.34, .57, 0); armL.rotation.z = -.26;
  const armR = mesh(new THREE.CapsuleGeometry(.085, .52, 3, 5), creatureMat, root); armR.position.set(.34, .57, 0); armR.rotation.z = .26;
  const legL = mesh(new THREE.CapsuleGeometry(.1, .34, 3, 5), creatureMat, root); legL.position.set(-.14, .2, 0);
  const legR = mesh(new THREE.CapsuleGeometry(.1, .34, 3, 5), creatureMat, root); legR.position.set(.14, .2, 0);
