  torch.intensity = torchOn ? 48 : 0;
  playerGlow.intensity = torchOn ? 1.65 : .16;
}
function gridBlocked(x, z) {
  if (!level || z < 0 || z >= level.layout.length || x < 0 || x >= level.layout[z].length) return true;
  return level.layout[z][x] !== '.';
}
function floorCell(x, z) { return !gridBlocked(x, z); }
function keyAt(x, z) { return seals.find(item => !item.collected && item.x === x && item.z === z); }
