import re
s=open('src/main.js').read()
for idx, block in enumerate(s.split("{ id: '")[1:],1):
    ch=block.split("'",1)[0]
    levels=re.findall(r"\{ name: '([^']+)', objective: '([^']+)', layout: \[(.*?)\], start: \[(\d+),(\d+)\], exit: \[(\d+),(\d+)\], keys: \[(.*?)\], enemy: \[(.*?)\]", block, re.S)
    for name,obj,layout_s,sx,sz,ex,ez,keys_s,enemy in levels:
      rows=re.findall(r"'([.#]+)'",layout_s); keys=[tuple(map(int,m)) for m in re.findall(r'\[(\d+),(\d+)\]',keys_s)]
      sx,sz,ex,ez=map(int,(sx,sz,ex,ez))
      ok=lambda x,z: 0<=z<len(rows) and 0<=x<len(rows[z]) and rows[z][x]=='.'
      from collections import deque
      q=deque([(sx,sz)]); seen={(sx,sz)}
      while q:
        x,z=q.popleft()
        for p in [(x+1,z),(x-1,z),(x,z+1),(x,z-1)]:
          if ok(*p) and p not in seen: seen.add(p);q.append(p)
      print(ch,name,'reachable exit', (ex,ez) in seen,'keys', [k in seen for k in keys], 'markers valid',ok(sx,sz),ok(ex,ez),[ok(*k) for k in keys])
